INSERT INTO courses (id, name, introduction, town_id, is_shared, created_by, created_at, updated_at) VALUES
                                                                                                         (1, '나만 알고싶은 망원동 코스', '조용한 골목 사이 나만 알고싶은 공간 모음', 3, TRUE, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
                                                                                                         (2, '망원동 빈티지샵 쇼핑 코스', '나만의 스타일을 발견하는 빈티지샵 쇼핑 코스', 3, TRUE, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
                                                                                                         (3, '책과 커피의 여백', '작은 서점과 한적한 카페 사이, 생각이 머무는 공간', 3, TRUE, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
                                                                                                         (4, '제로웨이스트 라이프 코스 ', '제로웨이스트 샵과 함께하는 혼놀 코스', 3, TRUE, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
                                                                                                         (5, '감각을 따라 걷는 하루', '나만의 향과 맛, 그리고 책의 결을 담는 시간', 3, TRUE, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
                                                                                                         (6, '소품샵 탐방 코스', '소소한 소비로 챙기는 확실한 기쁨', 3, TRUE, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
                                                                                                         (7, '나만 알고 싶은 감성 코스', '나만 알고 싶은 명소 모음', 3, TRUE, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
                                                                                                         (8, '망원동 감성 명소 총정리', '걷기만 해도 기분 좋아지는 망원동 대표 감성 스팟 모음', 3, TRUE, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
                                                                                                         (9, '조용한 평일 오후 코스', '혼자 걷기 좋은 시간, 조용하고 느긋한 동네 산책', 3, TRUE, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
                                                                                                         (10, '오롯이 나를 위한 하루', '아기자기한 소품샵부터 나를 찾는 1인 전시까지', 2, TRUE, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
                                                                                                         (11, '도심 속 느슨한 여백', '책과 녹음이 어우러진 힐링 코스', 2, TRUE, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
                                                                                                         (12, '취향을 수집하는 하루', '섬세한 취향을 따라 걷는 감성 스팟 루트', 2, TRUE, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
                                                                                                         (13, '노트북 펴고 낭만 한 스푼', '작업부터 당 충전까지 책임지는 하루 코스', 2, TRUE, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
                                                                                                         (14, '연희동 감성코스 한 바퀴', '혼자서도 알찬 연희동 혼놀 코스', 2, TRUE, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
                                                                                                         (15, '감상에 집중하고 싶은 날', '책과 음악, 한 편의 영화로 채우는 나만의 시간', 2, TRUE, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
                                                                                                         (16, '연희동 소품샵 코스', '소품샵 따라 걸으며 충전하는 소소한 기쁨', 2, TRUE, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
                                                                                                         (17, '혼자 쉬는 평일 오후 힐링 루트', '북적이지 않아 더 좋은 평일 오후 혼놀 코스', 2, TRUE, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
